30	function validarRecorrencia(categorias: Categoria[], dados: DadosRecorrencia, existente?: Recorrencia): Resultado<DadosRecorrencia> {
31	  const descricao = dados.descricao.trim();
32	  if (!descricao) return falha('Informe a descrição.', 'descricao');
33	  if (descricao.length > RECORRENCIA_DESCRICAO_MAX) return falha(`A descrição deve ter no máximo ${RECORRENCIA_DESCRICAO_MAX} caracteres.`, 'descricao');
34	  if (!Number.isInteger(dados.valor) || dados.valor <= 0) return falha('O valor deve ser maior que zero.', 'valor');
35	  const categoria = categorias.find((c) => c.id === dados.categoriaId);
36	  if (!categoria) return falha('Selecione uma categoria.', 'categoriaId');
37	  if (categoria.tipo !== dados.tipo) return falha(`A categoria deve ser de ${dados.tipo}.`, 'categoriaId');
38	  if (categoria.arquivada && existente?.categoriaId !== categoria.id) return falha('Esta categoria está arquivada.', 'categoriaId');
39	  return ok({ ...dados, descricao });
40	}
41	
42	export function criarRecorrencia(estado: AppState, dados: DadosRecorrencia): Resultado<AppState> {
43	  const v = validarRecorrencia(estado.categorias, dados);
44	  if (!v.ok) return v;
45	  return ok({ ...estado, recorrencias: [...estado.recorrencias, { id: novoId(), ...v.valor, ativa: true }] });
46	}
47	
48	export function editarRecorrencia(estado: AppState, id: string, dados: DadosRecorrencia): Resultado<AppState> {
49	  const atual = estado.recorrencias.find((r) => r.id === id);
50	  if (!atual) return falha('Recorrência não encontrada.');
51	  const v = validarRecorrencia(estado.categorias, dados, atual);
52	  if (!v.ok) return v;
53	  return ok({ ...estado, recorrencias: estado.recorrencias.map((r) => (r.id === id ? { ...r, ...v.valor } : r)) });
54	}
55	
56	export function alternarRecorrencia(estado: AppState, id: string, ativa: boolean): Resultado<AppState> {
57	  if (!estado.recorrencias.some((r) => r.id === id)) return falha('Recorrência não encontrada.');
58	  return ok({ ...estado, recorrencias: estado.recorrencias.map((r) => (r.id === id ? { ...r, ativa } : r)) });
59	}
