67	/** Até 3 meses completos antes do mês corrente, a partir do mês da primeira transação. */
68	export function mesesBase(transacoes: Transacao[], hoje: string): Mes[] {
69	  if (transacoes.length === 0) return [];
70	  const atual = mesDe(hoje);
71	  const primeiro = transacoes.reduce((min, t) => (t.data < min ? t.data : min), transacoes[0].data);
72	  const candidatos = Array.from({ length: MESES_BASE }, (_, i) => somarMeses(atual, -(MESES_BASE - i)));
73	  return candidatos.filter((m) => m >= mesDe(primeiro));
74	}
75	
76	export interface PontoProjecao {
77	  mes: Mes;
78	  saldo: Centavos;
79	}
80	
81	export type Projecao =
82	  | { tipo: 'sem-dados' }
83	  | {
84	      tipo: 'ok';
85	      mesesBase: Mes[];
86	      mediaReceitas: Centavos;
87	      mediaDespesas: Centavos;
88	      receitasRecorrentes: Centavos;
89	      despesasRecorrentes: Centavos;
90	      categoriasCobertas: string[];
91	      efeitoMensal: Centavos;
92	      saldoAtual: Centavos;
93	      meses: PontoProjecao[];
94	      primeiroNegativo: Mes | null;
95	    };
96	
97	/** Projeção simples e reproduzível à mão; veja SPEC/2026-10-01-dashboard-e-projecao-v2.md. */
98	export function calcularProjecao(estado: AppState, hoje: string, quantidade = MESES_PROJETADOS): Projecao {
99	  const base = mesesBase(estado.transacoes, hoje);
100	  const ativas = estado.recorrencias.filter((r) => r.ativa);
101	  if (base.length === 0 && ativas.length === 0) return { tipo: 'sem-dados' };
102	
103	  const cobertas = new Set(ativas.map((r) => `${r.tipo}|${r.categoriaId}`));
104	  const noBase = new Set(base);
105	  let receitas = 0;
106	  let despesas = 0;
107	  for (const t of estado.transacoes) {
108	    if (!noBase.has(mesDe(t.data)) || cobertas.has(`${t.tipo}|${t.categoriaId}`)) continue;
109	    if (t.tipo === 'receita') receitas += t.valor;
110	    else despesas += t.valor;
111	  }
112	  const n = base.length;
113	  const mediaReceitas = n === 0 ? 0 : Math.round(receitas / n);
114	  const mediaDespesas = n === 0 ? 0 : Math.round(despesas / n);
115	  const receitasRecorrentes = ativas.filter((r) => r.tipo === 'receita').reduce((s, r) => s + r.valor, 0);
116	  const despesasRecorrentes = ativas.filter((r) => r.tipo === 'despesa').reduce((s, r) => s + r.valor, 0);
117	  const efeitoMensal = mediaReceitas - mediaDespesas + receitasRecorrentes - despesasRecorrentes;
118	  const saldoAtual = saldoTotal(estado).total;
119	  const atual = mesDe(hoje);
120	  const meses = Array.from({ length: quantidade }, (_, i): PontoProjecao => ({ mes: somarMeses(atual, i + 1), saldo: saldoAtual + (i + 1) * efeitoMensal }));
121	
122	  return {
123	    tipo: 'ok',
124	    mesesBase: base,
125	    mediaReceitas,
126	    mediaDespesas,
127	    receitasRecorrentes,
128	    despesasRecorrentes,
129	    categoriasCobertas: [...new Set(ativas.map((r) => r.categoriaId))],
130	    efeitoMensal,
131	    saldoAtual,
132	    meses,
133	    primeiroNegativo: meses.find((p) => p.saldo < 0)?.mes ?? null,
134	  };
135	}
