137	// ------------------------------------------------------------------ dashboard
138	
139	export interface ResumoMes {
140	  receitas: Centavos;
141	  despesas: Centavos;
142	  resultado: Centavos;
143	}
144	
145	export function resumoMes(transacoes: Transacao[], mes: Mes): ResumoMes {
146	  let receitas = 0;
147	  let despesas = 0;
148	  for (const t of transacoes) {
149	    if (mesDe(t.data) !== mes) continue;
150	    if (t.tipo === 'receita') receitas += t.valor;
151	    else despesas += t.valor;
152	  }
153	  return { receitas, despesas, resultado: receitas - despesas };
154	}
155	
156	export interface FatiaCategoria {
157	  nome: string;
158	  valor: Centavos;
159	}
160	
161	/** Maiores categorias de despesa do mês; o restante é agrupado em "Outras". */
162	export function despesasPorCategoria(estado: AppState, mes: Mes, maximo = 5): FatiaCategoria[] {
163	  const nomes = new Map(estado.categorias.map((c) => [c.id, c.nome]));
164	  const totais = new Map<string, Centavos>();
165	  for (const t of estado.transacoes) {
166	    if (t.tipo !== 'despesa' || mesDe(t.data) !== mes) continue;
167	    totais.set(t.categoriaId, (totais.get(t.categoriaId) ?? 0) + t.valor);
168	  }
169	  const ordenadas = [...totais.entries()]
170	    .map(([id, valor]): FatiaCategoria => ({ nome: nomes.get(id) ?? 'Sem categoria', valor }))
171	    .sort((a, b) => b.valor - a.valor || a.nome.localeCompare(b.nome, 'pt-BR'));
172	  if (ordenadas.length <= maximo) return ordenadas;
173	  const resto = ordenadas.slice(maximo).reduce((s, f) => s + f.valor, 0);
174	  return [...ordenadas.slice(0, maximo), { nome: 'Outras', valor: resto }];
175	}
176	
177	export interface PontoMensal {
178	  mes: Mes;
179	  receitas: Centavos;
180	  despesas: Centavos;
181	}
182	
183	/** Receitas e despesas dos `quantidade` meses terminando em `mesFinal`. */
184	export function serieMensal(transacoes: Transacao[], mesFinal: Mes, quantidade = 6): PontoMensal[] {
185	  const meses = Array.from({ length: quantidade }, (_, i) => somarMeses(mesFinal, i - (quantidade - 1)));
186	  const pontos = new Map(meses.map((mes): [Mes, PontoMensal] => [mes, { mes, receitas: 0, despesas: 0 }]));
187	  for (const t of transacoes) {
188	    const p = pontos.get(mesDe(t.data));
189	    if (!p) continue;
190	    if (t.tipo === 'receita') p.receitas += t.valor;
191	    else p.despesas += t.valor;
192	  }
193	  return meses.map((m) => pontos.get(m)!);
194	}
