1	import { dataDaParcela } from './cartoes';
2	import { dataValida, mesDe } from './date';
3	import { novoId, proximoTempo } from './id';
4	import { DESCRICAO_MAX } from './transacoes';
5	import {
6	  falha,
7	  ok,
8	  type Agendamento,
9	  type AppState,
10	  type Categoria,
11	  type Centavos,
