19	export const REPETICOES_MIN = 1;
20	export const REPETICOES_MAX = 60;
21	export const DIAS_ALERTA = 7;
22	
23	export type SituacaoAgendamento = 'pago' | 'atrasado' | 'pendente';
24	
25	export function situacaoAgendamento(item: Agendamento, hoje: DataISO): SituacaoAgendamento {
26	  if (item.pagoEm) return 'pago';
27	  return item.vencimento < hoje ? 'atrasado' : 'pendente';
28	}
29	
30	function categoriaAtiva(categorias: Categoria[], id: string, tipo: TipoMovimento): boolean {
31	  const c = categorias.find((x) => x.id === id);
32	  return !!c && !c.arquivada && c.tipo === tipo;
33	}
34	
35	const contaAtiva = (estado: AppState, id: string) => estado.contas.some((c) => c.id === id && !c.arquivada);
36	
37	export interface DadosAgendamento {
38	  descricao: string;
39	  tipo: TipoMovimento;
40	  valor: Centavos;
41	  vencimento: DataISO;
42	  categoriaId: string;
43	  contaId?: string;
44	  /** Número de lançamentos mensais a criar (1 = sem recorrência). */
45	  repeticoes: number;
46	}
47	
48	export function criarAgendamentos(estado: AppState, dados: DadosAgendamento): Resultado<AppState> {
49	  const descricao = dados.descricao.trim();
50	  if (!descricao) return falha('Informe a descrição.', 'descricao');
51	  if (!Number.isInteger(dados.valor) || dados.valor <= 0) return falha('O valor deve ser maior que zero.', 'valor');
52	  if (!dataValida(dados.vencimento)) return falha('Informe um vencimento válido.', 'vencimento');
53	  if (!categoriaAtiva(estado.categorias, dados.categoriaId, dados.tipo)) {
54	    return falha(`Escolha uma categoria ativa de ${dados.tipo === 'despesa' ? 'despesa' : 'receita'}.`, 'categoriaId');
55	  }
56	  if (dados.contaId && !contaAtiva(estado, dados.contaId)) return falha('Escolha uma conta ativa.', 'contaId');
57	  const n = dados.repeticoes;
58	  if (!Number.isInteger(n) || n < REPETICOES_MIN || n > REPETICOES_MAX) {
59	    return falha(`As repetições devem ficar entre ${REPETICOES_MIN} e ${REPETICOES_MAX}.`, 'repeticoes');
60	  }
61	
62	  const grupoId = novoId();
63	  const novos: Agendamento[] = Array.from({ length: n }, (_, i) => {
64	    const sufixo = n > 1 ? ` (${i + 1}/${n})` : '';
65	    return {
66	      id: novoId(),
67	      descricao: descricao.slice(0, DESCRICAO_MAX - sufixo.length) + sufixo,
68	      tipo: dados.tipo,
69	      valor: dados.valor,
70	      vencimento: dataDaParcela(dados.vencimento, i),
71	      categoriaId: dados.categoriaId,
72	      ...(dados.contaId ? { contaId: dados.contaId } : {}),
73	      ...(n > 1 ? { serie: { grupoId, numero: i + 1, total: n } } : {}),
74	      criadoEm: proximoTempo(),
75	    };
76	  });
77	  return ok({ ...estado, agenda: [...estado.agenda, ...novos] });
78	}
