86	/** Dá baixa: cria a transação real e liga o lançamento a ela. Recusa lançamentos já pagos. */
87	export function marcarComoPago(estado: AppState, id: string, dados: DadosBaixa): Resultado<AppState> {
88	  const item = estado.agenda.find((a) => a.id === id);
89	  if (!item) return falha('Lançamento não encontrado.');
90	  if (item.pagoEm) return falha('Este lançamento já foi pago.');
91	  if (!contaAtiva(estado, dados.contaId)) return falha('Escolha uma conta ativa.', 'contaId');
92	  if (!categoriaAtiva(estado.categorias, dados.categoriaId, item.tipo)) {
93	    return falha(`Escolha uma categoria ativa de ${item.tipo === 'despesa' ? 'despesa' : 'receita'}.`, 'categoriaId');
94	  }
95	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
96	
97	  const transacao: Transacao = {
98	    id: novoId(),
99	    contaId: dados.contaId,
100	    categoriaId: dados.categoriaId,
101	    tipo: item.tipo,
102	    valor: item.valor,
103	    data: dados.data,
104	    descricao: item.descricao,
105	    criadaEm: proximoTempo(),
106	  };
107	  return ok({
108	    ...estado,
109	    transacoes: [...estado.transacoes, transacao],
