179	/** Dias da grade do mês: `null` nas células vazias antes do dia 1 (semana começa no domingo). */
180	export function diasDaGrade(mes: Mes): (DataISO | null)[] {
181	  const [ano, m] = mes.split('-').map(Number);
182	  const primeiro = new Date(Date.UTC(ano, m - 1, 1)).getUTCDay();
183	  const total = new Date(Date.UTC(ano, m, 0)).getUTCDate();
184	  return [
185	    ...Array.from({ length: primeiro }, () => null),
186	    ...Array.from({ length: total }, (_, i) => `${mes}-${String(i + 1).padStart(2, '0')}`),
187	  ];
188	}
