41	/** Vence no mês do fechamento se o vencimento é depois do fechamento; senão, no mês seguinte. */
42	export function vencimentoFatura(config: CartaoConfig, mes: Mes): DataISO {
43	  const mesVenc = config.diaVencimento > config.diaFechamento ? mes : somarMeses(mes, 1);
44	  return `${mesVenc}-${dia2(config.diaVencimento)}`;
45	}
