53	export function transacoesDaFatura(estado: AppState, conta: Conta, mes: Mes): Transacao[] {
54	  if (!conta.cartao) return [];
55	  const { inicio, fim } = cicloFatura(conta.cartao, mes);
56	  return estado.transacoes
57	    .filter((t) => t.contaId === conta.id && t.data >= inicio && t.data <= fim)
58	    .sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : b.criadaEm - a.criadaEm));
59	}
