61	/** Compras menos estornos (receitas) no ciclo. */
62	export function totalFatura(transacoes: Transacao[]): Centavos {
63	  return transacoes.reduce((s, t) => s + (t.tipo === 'despesa' ? t.valor : -t.valor), 0);
64	}
