169	/** Exclui só a parcela ou todas as parcelas do mesmo grupo. */
170	export function excluirParcela(estado: AppState, transacaoId: string, escopo: EscopoExclusao): Resultado<AppState> {
171	  const alvo = estado.transacoes.find((t) => t.id === transacaoId);
172	  if (!alvo) return falha('Transação não encontrada.');
173	  const grupo = alvo.parcela?.grupoId;
174	  const remover = (t: Transacao) => (escopo === 'todas' && grupo ? t.parcela?.grupoId === grupo : t.id === transacaoId);
175	  return ok({ ...estado, transacoes: estado.transacoes.filter((t) => !remover(t)) });
176	}
