113	/** Data da parcela k (1 = primeira): k−1 meses depois, no mesmo dia, limitado ao último dia do mês. */
114	export function dataDaParcelaDivida(primeira: DataISO, numero: number): DataISO {
115	  const mes = somarMeses(mesDe(primeira), numero - 1);
116	  const [ano, m] = mes.split('-').map(Number);
117	  const dia = Math.min(Number(primeira.slice(8, 10)), diasNoMes(ano, m));
118	  return `${mes}-${String(dia).padStart(2, '0')}`;
119	}
