158	/** Compara Price e SAC para os mesmos termos, sem salvar nada. */
159	export function simular(termos: Omit<TermosDivida, 'sistema'>): Record<SistemaAmortizacao, ResumoSimulacao> {
160	  const resumir = (sistema: SistemaAmortizacao): ResumoSimulacao => {
161	    const linhas = calcularParcelas({ ...termos, sistema });
162	    const totalPago = somar(linhas.map((l) => l.parcela));
163	    return { primeiraParcela: linhas[0].parcela, ultimaParcela: linhas[linhas.length - 1].parcela, totalJuros: totalPago - termos.principal, totalPago };
164	  };
165	  return { price: resumir('price'), sac: resumir('sac') };
166	}
